function fetchTencent(codes) {
  return new Promise((resolve, reject) => {
    const list = codes.map(c => (String(secidOf(c))[0] === '1' ? 'sh' : 'sz') + c);
    if (!list.length) { reject(new Error('no codes')); return; }
    const s = document.createElement('script');
    let done = false;
    const timer = setTimeout(() => finish(new Error('timeout')), 8000);
    function finish(err, n) {
      if (done) return; done = true;
      clearTimeout(timer);
      try { s.remove(); } catch (e) {}
      if (err) reject(err); else resolve(n);
    }
    s.charset = 'gbk';
    s.onload = () => {
      let n = 0;
      list.forEach(k => {
        const raw = window['v_' + k];
        if (typeof raw !== 'string') return;
        const f = raw.split('~');
        const price = Number(f[3]), prev = Number(f[4]);
        if (!(price > 0)) return;
        S.px[k.slice(2)] = {
          price: price, chg: Number(f[32]) || 0, prev: prev > 0 ? prev : price,
          name: f[1], at: Date.now()
        };
        n++;
      });
      finish(n ? null : new Error('empty'), n);
    };
    s.onerror = () => finish(new Error('net'));
    s.src = 'https://qt.gtimg.cn/q=' + list.join(',') + '&_=' + Date.now();
    (document.head || document.body).appendChild(s);
  });
}

