function fetchTencent(codes) {
  return new Promise((resolve, reject) => {
    const codes6 = codes.map(code6).filter(Boolean);
    const list = codes6.map(c => (String(secidOf(c))[0] === '1' ? 'sh' : 'sz') + c);
    if (!list.length) { reject(new Error('no codes')); return; }
    const s = document.createElement('script');
    let done = false;
    const timer = setTimeout(() => finish(new Error('timeout')), 8000);
    function finish(err, res) {
      if (done) return; done = true;
      clearTimeout(timer);
      try { s.remove(); } catch (e) {}
      if (err) reject(err); else resolve(res);
    }
    s.charset = 'gbk';
    s.onload = () => {
      let n = 0;
      const missing = [];
      list.forEach(k => {
        const raw = window['v_' + k];
        const f = typeof raw === 'string' ? raw.split('~') : [];
        const code = code6(f[2] || k.slice(2));
        const price = Number(f[3]), prev = Number(f[4]);
        if (!(price > 0) || !code) { if (code) missing.push(code); return; }
        S.px[code] = {
          price: price, chg: Number(f[32]) || 0, prev: prev > 0 ? prev : price,
          name: f[1], at: Date.now()
        };
        n++;
      });
      // 批里缺的不要当成整批成功，交给东财补。一只都没有才算失败。
      if (!n) finish(new Error('empty'));
      else finish(null, { n: n, missing: missing });
    };
    s.onerror = () => finish(new Error('net'));
    s.src = 'https://qt.gtimg.cn/q=' + list.join(',') + '&_=' + Date.now();
    (document.head || document.body).appendChild(s);
  });
}

